            "\u09a1\u09bf\u099a\u0995\u09f0\u09cd\u09a1, \u09b9\u09cb\u09f1\u09be\u099f\u099b\u098f\u09aa, \u099f\u09c7\u09b2\u09bf\u0997\u09cd\u09f0\u09be\u09ae, \u099a\u09bf\u0997\u09a8\u09c7\u09b2, \u09ae\u09be\u0987\u0995\u09cd\u09f0\u2019\u099b\u09ab\u09cd\u099f \u099f\u09bf\u09ae, \u099c\u09c1\u09ae, \u09b8\u09cd\u09b2\u09c7\u0995, \u099a\u09c7\u099f\u099c\u09bf\u09aa\u09bf\u099f\u09bf, \u09b8\u09cd\u09aa\u099f\u09bf\u09ab\u09be\u0987, \u09ad\u09bf\u098f\u09b2\u099a\u09bf, \u0997\u09c1\u0997\u09b2 \u09a1\u09cd\u09f0\u09be\u0987\u09ad, \u0985\u2019\u09ac\u09bf\u098f\u099b \u09b7\u09cd\u099f\u09c1\u09a1\u09bf\u0985\u2019, \u09ad\u09bf\u098f\u099b \u0995\u2019\u09a1, \u0986\u09f0\u09c1 \u09ae\u09c7\u09a1\u09c7\u09b2\u0964",
