            "\u0790\u07b0\u0793\u07a9\u0789\u07b0\u060c \u0787\u07ac\u0795\u07a8\u0786\u07b0 \u078e\u07ad\u0789\u07b0\u0790\u07b0\u060c \u0787\u07a9\u0787\u07ad \u0787\u07ac\u0795\u07b0\u060c \u0794\u07ab\u0784\u07a8\u0790\u07ae\u078a\u07b0\u0793\u07b0 \u0786\u07a6\u0782\u07ac\u0786\u07b0\u0793\u07b0\u060c \u0784\u07ac\u0793\u07b0\u078d\u07b0.\u0782\u07ac\u0793\u07b0\u060c \u0796\u07a9\u0787\u07af\u0796\u07a9 \u078e\u07ac\u078d\u07ac\u0786\u07b0\u0790\u07a9\u060c \u0783\u07a8\u0787\u07a6\u0793\u07b0 \u0786\u07b0\u078d\u07a6\u0787\u07a8\u0782\u07b0\u0793\u07b0\u060c \u0783\u07ae\u0786\u07b0\u0790\u07b0\u0793\u07a7 \u078e\u07ad\u0789\u07b0\u0790\u07b0 \u078d\u07af\u0782\u07b0\u0797\u07a7\u060c \u0787\u07ac\u0789\u07ac\u0792\u07af\u0782\u07b0 \u078e\u07ad\u0789\u07b0\u0790\u07b0\u060c itch.io\u060c \u0780\u07af\u0794\u07af\u0795\u07b0\u078d\u07ad\u060c \u0789\u07a6\u0787\u07a8\u0782\u07b0\u0786\u07b0\u0783\u07a7\u078a\u07b0\u0793\u07b0 \u078d\u07af\u0782\u07b0\u0797\u07a7\u060c \u0787\u07a6\u078b\u07a8 \u0787\u07ac\u0786\u07b0\u0790\u07b0\u0784\u07ae\u0786\u07b0\u0790\u07b0 \u0787\u07ac\u0788\u07ac. \u0787\u07a8\u0782\u07b0\u0790\u07b0\u0793\u07af\u078d\u07b0 \u0786\u07ae\u0781\u07b0\u078a\u07a6\u0787\u07a8\u0788\u07a7 \u078e\u07ad\u0789\u07b0\u078c\u07a6\u0787\u07b0 \u0787\u07ac\u0789\u07a9\u0780\u07aa\u0782\u07b0\u078e\u07ac \u078d\u07af\u0782\u07b0\u0797\u07a7\u078e\u07ac \u0789\u07ac\u0782\u07ab\u0787\u07a8\u0782\u07b0 \u078a\u07ac\u0782\u07b0\u0782\u07a7\u0782\u07ac\u0787\u07ac\u0788\u07ac.",
            "\u0786\u07b0\u0783\u07af\u0789\u07b0\u060c \u0789\u07a6\u0787\u07a8\u0786\u07b0\u0783\u07ae\u0790\u07ae\u078a\u07b0\u0793\u07b0 \u0787\u07ac\u0796\u07b0\u060c \u078a\u07a6\u0794\u07a6\u0783\u078a\u07ae\u0786\u07b0\u0790\u07b0\u060c \u0784\u07b0\u0783\u07ad\u0788\u07b0\u060c \u0788\u07a8\u0788\u07a6\u078d\u07b0\u0791\u07a9\u060c \u0787\u07a6\u078b\u07a8 \u0787\u07ae\u0795\u07ac\u0783\u07a7 \u0796\u07a9\u0787\u07ac\u0786\u07b0\u0790\u07b0 \u0787\u07ac\u0788\u07ac.",
            "\u0791\u07a8\u0790\u07b0\u0786\u07af\u0791\u07b0\u060c \u0788\u07a6\u0793\u07b0\u0790\u07b0\u0787\u07ac\u0795\u07b0\u060c \u0793\u07ac\u078d\u07ac\u078e\u07b0\u0783\u07a7\u0789\u07b0\u060c \u0790\u07a8\u078e\u07b0\u0782\u07a6\u078d\u07b0\u060c \u0789\u07a6\u0787\u07a8\u0786\u07b0\u0783\u07ae\u0790\u07ae\u078a\u07b0\u0793\u07b0 \u0793\u07a9\u0789\u07b0\u0790\u07b0\u060c \u0792\u07ab\u0789\u07b0\u060c \u0790\u07b0\u078d\u07ac\u0786\u07b0\u060c \u0797\u07ac\u0793\u07b0\u0796\u07a9\u0795\u07a9\u0793\u07a9\u060c \u0790\u07b0\u0795\u07ae\u0793\u07a8\u078a\u07a6\u0787\u07a8\u060c \u0788\u07a9\u0787\u07ac\u078d\u07b0\u0790\u07a9\u060c \u078e\u07ab\u078e\u07aa\u078d\u07b0 \u0791\u07b0\u0783\u07a6\u0787\u07a8\u0788\u07b0\u060c \u0787\u07af\u0784\u07a9\u0787\u07ac\u0790\u07b0 \u0790\u07b0\u0793\u07ab\u0791\u07a8\u0787\u07af\u060c \u0788\u07a9\u0787\u07ac\u0790\u07b0 \u0786\u07af\u0791\u07b0\u060c \u0787\u07a6\u078b\u07a8 \u0789\u07ac\u0791\u07a6\u078d\u07b0 \u0787\u07ac\u0788\u07ac.",
            "\u0794\u07ab\u0793\u07a8\u0787\u07aa\u0784\u07b0\u060c \u0787\u07a8\u0782\u07b0\u0790\u07b0\u0793\u07a6\u078e\u07b0\u0783\u07a7\u0789\u07b0\u060c \u0793\u07a8\u0786\u07b0\u0793\u07ae\u0786\u07b0\u060c \u078a\u07ad\u0790\u07b0\u0784\u07aa\u0786\u07b0\u060c \u0789\u07ac\u0790\u07ac\u0782\u07b0\u0796\u07a6\u0783\u060c \u0787\u07a6\u078b\u07a8 \u078e\u07ab\u078e\u07aa\u078d\u07b0 \u0789\u07ac\u0795\u07b0\u0790\u07b0 \u0787\u07a8\u0782\u07b0\u0790\u07b0\u0793\u07af\u078d\u07b0 \u0786\u07aa\u0783\u07aa\u0789\u07aa\u0782\u07b0 \u0788\u07a8\u0782\u07b0\u0791\u07af\u0792\u07b0 \u0787\u07ac\u0795\u07b0 \u0782\u07aa\u0788\u07a6\u078c\u07a6 \u0795\u07a9\u0791\u07a6\u0784\u07b0\u078d\u07a8\u0794\u07aa\u0787\u07ad\u078e\u07ac \u078e\u07ae\u078c\u07aa\u078e\u07a6\u0787\u07a8 \u078a\u07a7\u0780\u07a6\u078e\u07a6 \u0786\u07aa\u0783\u07ac\u0788\u07ac\u0787\u07ac\u0788\u07ac.",
            "\u0789\u07a6\u078c\u07a9\u078e\u07a6\u0787\u07a8\u0788\u07a7 ADD APP \u0784\u07ad\u0782\u07aa\u0782\u07b0\u0786\u07ae\u0781\u07b0\u078e\u07ac\u0782\u07b0 .exe\u060c .lnk\u060c \u0782\u07aa\u0788\u07a6\u078c\u07a6 .appref-ms \u078a\u07a6\u0787\u07a8\u078d\u07b0 \u0787\u07ac\u0787\u07b0 \u0787\u07a8\u078c\u07aa\u0783\u07aa\u0786\u07aa\u0783\u07aa\u0782\u07b0. \u0787\u07ad\u078e\u07ac \u0786\u07a7\u0791\u07a6\u0781\u07b0 \u0783\u07a6\u0782\u078e\u07a6\u0785\u07a6\u0781\u07b0 \u0786\u07b0\u078d\u07a8\u0786\u07b0\u0786\u07ae\u0781\u07b0 \u0786\u07ad-\u078d\u07af\u0782\u07b0\u0797\u07a6\u0783 \u0787\u07a8\u0782\u07b0 \u0782\u07a6\u0787\u07b0\u078c\u07a7\u078d\u07a7\u0781\u07ac\u0788\u07ac. \u0780\u07a6\u0789\u07a6\u0787\u07ac\u0786\u07a6\u0782\u07a8 \u0787\u07a8\u0782\u07b0\u0790\u07b0\u0793\u07af\u078d\u07b0 \u0786\u07aa\u0783\u07ac\u0788\u07a8\u078a\u07a6\u0787\u07a8\u0788\u07a7 \u0787\u07a6\u078b\u07a8 \u078d\u07af\u0782\u07b0\u0797\u07b0 \u0786\u07aa\u0783\u07ac\u0788\u07ad \u0787\u07ac\u0795\u07b0\u078c\u07a6\u0787\u07b0 \u078b\u07a6\u0787\u07b0\u0786\u07a7\u078d\u07a6\u0787\u07ac\u0788\u07ac.",
            "\u0787\u07ac\u0795\u07b0\u078d\u07a8\u0786\u07ad\u079d\u07a6\u0782\u07b0\u078c\u07a6\u0786\u07a7\u0787\u07a8 \u079d\u07af\u0793\u07b0\u0786\u07a6\u0793\u07b0\u0790\u07b0",
            "\u0780\u07aa\u0783\u07a8\u0780\u07a7 \u078a\u07a6\u0787\u07a8\u078d\u07b0\u0787\u07ac\u0786\u07ac\u0788\u07ac",
    ];

