            "\u0f56\u0f62\u0fa1\u0f0b\u0f66\u0fa4\u0fb2\u0f7c\u0f51\u0f0b\u0f51\u0f44\u0f0b\u0f49\u0f72\u0f53\u0f0b\u0f62\u0f7a\u0f60\u0f72\u0f0b\u0f58\u0f49\u0f7a\u0f53\u0f0b\u0f46\u0f66\u0f0d",
            "\u0f42\u0f5e\u0f72\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f61\u0f7c\u0f51\u0f0b\u0f54\u0f60\u0f72\u0f0b\u0f42\u0fb3\u0f7c\u0f42\u0f0b\u0f62\u0f72\u0f58\u0f0b\u0f5a\u0f74\u0f0b / \u0f54\u0f72\u0f0b\u0f4c\u0f56\u0f0b\u0f63\u0f74\u0f0b\u0f68\u0f7a\u0f0b\u0f5a\u0f74\u0f0d",
            "\u0f62\u0f44\u0f0b\u0f42\u0f72\u0f0b\u0f41\u0f0b\u0f66\u0f90\u0f7c\u0f44\u0f66\u0f0d",
            "\u0f56\u0f4f\u0f74\u0f56\u0f0d",
            "\u0f40\u0f7a\u0f0b-\u0f60\u0f42\u0f7c\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f58\u0f72\u0f0b\u0f63\u0f74\u0f0b \u0f42\u0fb3\u0f7c\u0f42\u0f0b\u0f62\u0f72\u0f58\u0f0b\u0f41\u0f0b\u0f66\u0f90\u0f7c\u0f44\u0f0b\u0f56\u0f62\u0f90\u0fb1\u0f56\u0f0d",
            "\u0f66\u0f7a\u0f63\u0f0b\u0f60\u0f50\u0f74\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f61\u0f7c\u0f51\u0f0b\u0f54\u0f60\u0f72\u0f0b\u0f42\u0fb3\u0f7c\u0f42\u0f0b\u0f62\u0f72\u0f58\u0f0b\u0f5a\u0f74\u0f0b \u0f67\u0f7a\u0f0b\u0f58\u0f0b\u0f63\u0f66\u0f0b\u0f50\u0f7c\u0f0b\u0f56\u0f40\u0f7c\u0f51\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f61\u0f7c\u0f51\u0f54\u0f0b \u0f61\u0f44\u0f0b\u0f53\u0f0b \u0f62\u0f92\u0fb1\u0f56\u0f0b\u0f66\u0f90\u0fb1\u0f7c\u0f62\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f61\u0f7c\u0f51\u0f0b\u0f54\u0f60\u0f72\u0f0b\u0f42\u0fb3\u0f7c\u0f42\u0f0b\u0f62\u0f72\u0f58\u0f0b \u0f61\u0f44\u0f0b\u0f53\u0f0b \u0f58\u0f42\u0fb1\u0f7c\u0f42\u0f66\u0f0b\u0f50\u0f56\u0f66\u0f0b\u0f58\u0f7a\u0f53\u0f0d",
            "\u0f58\u0f42\u0fb1\u0f7c\u0f42\u0f66\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f63\u0f58\u0f0b\u0f62\u0fa9\u0f0b\u0f56\u0f66\u0f90\u0fb2\u0f51\u0f0b\u0f42\u0f4f\u0f44\u0f0b\u0f0d",
            "\u0f41\u0fb1\u0f7c\u0f51\u0f0b\u0f40\u0fb1\u0f72\u0f66\u0f0b\u0f62\u0fa9\u0f0b\u0f56\u0f66\u0f90\u0fb2\u0f51\u0f0b\u0f42\u0f4f\u0f44\u0f0b\u0f53\u0f72\u0f0b\u0f68\u0f72\u0f53\u0f0b\u0f58\u0f72\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f63\u0f58\u0f0b\u0f42\u0fb1\u0f72\u0f0b\u0f64\u0f74\u0f63\u0f0b\u0f58\u0f58\u0f0b\u0f42\u0fb1\u0f72\u0f0b\u0f68\u0f7a\u0f56\u0f0b\u0f62\u0f9f\u0f0b\u0f60\u0f51\u0f72\u0f0b\u0f68\u0f7a\u0f56\u0f0d",
            "\u0f62\u0fa9\u0f0b\u0f56\u0f66\u0f90\u0fb2\u0f51\u0f0b\u0f42\u0f4f\u0f44\u0f0b\u0f53\u0f72\u0f60\u0f72\u0f0b\u0f51\u0f7c\u0f53\u0f0b\u0f63\u0f74\u0f0b \u0f58\u0f42\u0fb1\u0f7c\u0f42\u0f66\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f63\u0f58\u0f0b\u0f5a\u0f74\u0f0b\u0f58\u0f0b\u0f63\u0f74\u0f66\u0f0d",
            "\u0f58\u0f42\u0fb1\u0f7c\u0f42\u0f66\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f58\u0f50\u0f74\u0f51\u0f0b\u0f41\u0f0b\u0f62\u0f90\u0fb1\u0f56\u0f66\u0f0d",
            "\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f63\u0f58\u0f0b\u0f42\u0fb1\u0f72\u0f0b\u0f58\u0f72\u0f44\u0f0b\u0f0d",
            "\u0f68\u0f7a\u0f46\u0f0b\u0f4a\u0f72\u0f0b\u0f4a\u0f72\u0f0b\u0f54\u0f72\u0f0b\u0f51\u0f44\u0f0b\u0f68\u0f7a\u0f46\u0f0b\u0f4a\u0f72\u0f0b\u0f4a\u0f72\u0f0b\u0f54\u0f72\u0f0b\u0f68\u0f7a\u0f66\u0f72\u0f0b\u0f60\u0f56\u0fb2\u0f7a\u0f63\u0f0b\u0f63\u0f58\u0f0b\u0f5a\u0f74\u0f0b\u0f62\u0f92\u0fb1\u0f56\u0f0b\u0f66\u0f90\u0fb1\u0f7c\u0f62\u0f0b\u0f60\u0f56\u0f51\u0f5d\u0f0b\u0f68\u0f72\u0f53\u0f0d",
            "\u0f44\u0f7c\u0f66\u0f0b\u0f60\u0f51\u0fb2\u0f0b\u0f56\u0f60\u0f72\u0f0b\u0f56\u0f62\u0f97\u0f7c\u0f51\u0f0b\u0f51\u0f7c\u0f53\u0f0b\u0f46\u0f0b\u0f5a\u0f44\u0f0b\u0f0d",
            "\u0f62\u0fb3\u0f44\u0f66\u0f58\u0f0b \u0f68\u0f7a\u0f0b\u0f54\u0f72\u0f42\u0f0b\u0f62\u0fa9\u0f7a\u0f51\u0f0b\u0f62\u0f72\u0f42\u0f66\u0f0b \u0f68\u0f72\u0f0b\u0f68\u0f7a\u0f0b\u0f68\u0f7a\u0f54\u0f0b \u0f61\u0f74\u0f0b\u0f56\u0f72\u0f0b\u0f66\u0f7c\u0f55\u0f4a\u0f0b\u0f58\u0f50\u0f74\u0f51\u0f0b\u0f63\u0f58\u0f0b \u0f56\u0f71\u0f0b\u0f4a\u0f63\u0f0b\u0f4c\u0f7c\u0f0b\u0f4a\u0f72\u0f0b \u0f47\u0f72\u0f0b\u0f68\u0f7c\u0f0b\u0f47\u0f72\u0f0b \u0f42\u0f71\u0f0b\u0f63\u0f7a\u0f42\u0f0b\u0f66\u0f72\u0f0b \u0f62\u0f60\u0f72\u0f4a\u0f0b \u0f58\u0f41\u0f7c\u0f0b\u0f66\u0fa4\u0fb2\u0f7c\u0f51\u0f0b\u0f54\u0f0b \u0f62\u0f7c\u0f40\u0f0b\u0f66\u0f72\u0f0b\u0f4a\u0f62\u0f0b\u0f62\u0fa9\u0f7a\u0f51\u0f0b\u0f62\u0f72\u0f42\u0f66\u0f0b\u0f60\u0f42\u0f7c\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f58\u0f72\u0f0b \u0f68\u0f7a\u0f0b\u0f58\u0f0b\u0f5b\u0f7c\u0f53\u0f0b\u0f62\u0fa9\u0f7a\u0f51\u0f0b\u0f62\u0f72\u0f42\u0f66\u0f0b itch.io \u0f67\u0f7c\u0f0b\u0f61\u0f7c\u0f0b\u0f54\u0f7a\u0f0b\u0f63\u0f7a\u0f0b \u0f58\u0f60\u0f7a\u0f0b\u0f41\u0f72\u0f0b\u0f62\u0f55\u0f4a\u0f0b\u0f60\u0f42\u0f7c\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f58\u0f72\u0f0b \u0f51\u0f7a\u0f0b\u0f63\u0f66\u0f0b \u0f68\u0f7a\u0f42\u0f66\u0f72\u0f0b\u0f56\u0f7c\u0f42\u0f66\u0f72\u0f0b\u0f5a\u0f74\u0f0b\u0f68\u0f72\u0f53\u0f0d \u0f42\u0f5e\u0f72\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f61\u0f7c\u0f51\u0f0b\u0f54\u0f60\u0f72\u0f0b\u0f62\u0fa9\u0f7a\u0f51\u0f58\u0f7c\u0f0b\u0f5a\u0f74\u0f0b \u0f41\u0f7c\u0f44\u0f0b\u0f62\u0f60\u0f72\u0f0b\u0f60\u0f42\u0f7c\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f58\u0f72\u0f0b\u0f42\u0f72\u0f0b\u0f51\u0f40\u0f62\u0f0b\u0f46\u0f42\u0f0b\u0f53\u0f44\u0f0b\u0f60\u0f56\u0fb1\u0f74\u0f44\u0f58\u0f0b\u0f68\u0f72\u0f53\u0f0d",
            "\u0f40\u0f7c\u0f62\u0f7c\u0f58\u0f0b\u0f51\u0f44\u0f0b\u0f58\u0f60\u0f72\u0f0b\u0f40\u0f7c\u0f62\u0f7c\u0f0b\u0f66\u0f7c\u0f55\u0f4a\u0f72\u0f0b\u0f68\u0f7a\u0f47\u0f0b \u0f55\u0f0b\u0f61\u0f62\u0f0b\u0f55\u0f7c\u0f42\u0f66\u0f72\u0f0b \u0f56\u0f7a\u0f62\u0f7a\u0f56\u0f0b \u0f5d\u0f72\u0f0b\u0f5d\u0f63\u0f0b\u0f4c\u0f72\u0f0b \u0f51\u0f7a\u0f0b\u0f63\u0f66\u0f0b \u0f68\u0f7c\u0f0b\u0f54\u0f7a\u0f0b\u0f62\u0f0b\u0f47\u0f72\u0f0b\u0f68\u0f7a\u0f42\u0f66\u0f72\u0f0b\u0f5a\u0f74\u0f0b\u0f68\u0f72\u0f53\u0f0d",
            "\u0f4c\u0f72\u0f66\u0f72\u0f0b\u0f40\u0f7c\u0f62\u0f0b\u0f4c\u0f72\u0f0b \u0f5d\u0f4a\u0f0b\u0f68\u0f7a\u0f54\u0f0b \u0f4a\u0f7a\u0f0b\u0f63\u0f72\u0f0b\u0f42\u0fb7\u0f0b\u0f62\u0f58\u0f0b \u0f56\u0f62\u0fa1\u0f0b\u0f62\u0f9f\u0f42\u0f66\u0f0b \u0f58\u0f60\u0f72\u0f0b\u0f40\u0f7c\u0f62\u0f7c\u0f0b\u0f66\u0f7c\u0f55\u0f4a\u0f0b\u0f66\u0fa1\u0f7a\u0f0b\u0f5a\u0f53\u0f0b \u0f5f\u0f74\u0f58\u0f0b \u0f66\u0f72\u0f0b\u0f63\u0f7a\u0f40\u0f0b \u0f45\u0f71\u0f4a\u0f0b\u0f47\u0f72\u0f0b\u0f54\u0f72\u0f0b\u0f4a\u0f72\u0f0b \u0f68\u0f72\u0f66\u0f72\u0f0b\u0f54\u0f7c\u0f0b\u0f4a\u0f72\u0f0b\u0f55\u0f60\u0f72\u0f0b \u0f5d\u0f72\u0f0b\u0f68\u0f7a\u0f63\u0f0b\u0f66\u0f72\u0f0b \u0f42\u0f74\u0f0b\u0f42\u0f74\u0f63\u0f0b\u0f51\u0fb2\u0f60\u0f72\u0f0b\u0f56\u0f72\u0f0b \u0f68\u0f7c\u0f0b\u0f56\u0f72\u0f0b\u0f68\u0f7a\u0f66\u0f72\u0f0b \u0f66\u0f72\u0f0b\u0f4a\u0f74\u0f0b\u0f4c\u0f72\u0f60\u0f7c\u0f0b \u0f5d\u0f72\u0f0b\u0f68\u0f7a\u0f66\u0f72\u0f0b\u0f40\u0f7c\u0f4c\u0f0b \u0f51\u0f7a\u0f0b\u0f63\u0f66\u0f0b \u0f62\u0f9f\u0f42\u0f66\u0f0b\u0f58\u0f0b\u0f5a\u0f74\u0f0b\u0f68\u0f72\u0f53\u0f0d",
            "\u0f61\u0f74\u0f0b\u0f4a\u0f74\u0f56\u0f0b\u0f51\u0f44\u0f0b \u0f68\u0f72\u0f53\u0f0b\u0f4a\u0f62\u0f0b\u0f53\u0f7a\u0f4a\u0f0b \u0f4a\u0f72\u0f40\u0f0b\u0f4a\u0f7c\u0f42\u0f0b \u0f55\u0f7a\u0f66\u0f72\u0f0b\u0f56\u0f74\u0f40\u0f0b \u0f58\u0f7a\u0f0b\u0f66\u0f7a\u0f53\u0f47\u0f62\u0f0b \u0f51\u0f7a\u0f0b\u0f63\u0f66\u0f0b \u0f42\u0f74\u0f0b\u0f42\u0f71\u0f63\u0f0b\u0f66\u0f56\u0f0b\u0f41\u0fb2\u0f0b\u0f5a\u0f74\u0f0b \u0f5d\u0f72\u0f53\u0f0b\u0f4c\u0f7c\u0f0b\u0f68\u0f7a\u0f54\u0f0b \u0f61\u0f44\u0f0b\u0f53\u0f0b \u0f54\u0f72\u0f0b\u0f4c\u0f56\u0f0b\u0f63\u0f74\u0f0b\u0f68\u0f7a\u0f0b\u0f66\u0fa6\u0f7a\u0f0b \u0f42\u0f5e\u0f72\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f56\u0f60\u0f72\u0f0b\u0f66\u0f90\u0f56\u0f66\u0f0b \u0f56\u0f62\u0f9f\u0f42\u0f0b\u0f51\u0f54\u0fb1\u0f51\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f5a\u0f74\u0f42\u0f66\u0f0d",
            ".exe, .lnk, \u0f61\u0f44\u0f0b\u0f53\u0f0b .appref-ms \u0f61\u0f72\u0f42\u0f0b\u0f66\u0fa3\u0f7c\u0f51\u0f0b\u0f41\u0f0b\u0f66\u0f90\u0f7c\u0f44\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f53\u0f72\u0f0b\u0f63\u0f74\u0f0b \u0f42\u0f7c\u0f44\u0f0b\u0f63\u0f74\u0f0b ADD APP \u0f63\u0f42\u0f0b\u0f63\u0f7a\u0f53\u0f0b\u0f60\u0f50\u0f56\u0f0d \u0f40\u0f7a\u0f0b-\u0f60\u0f42\u0f7c\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f58\u0f72\u0f0b\u0f63\u0f66\u0f0b\u0f56\u0f4f\u0f7c\u0f53\u0f0b\u0f42\u0f4f\u0f44\u0f0b\u0f53\u0f72\u0f0b\u0f63\u0f74\u0f0b \u0f51\u0f7a\u0f0b\u0f42\u0f72\u0f0b\u0f64\u0f7c\u0f42\u0f0b\u0f56\u0fb1\u0f44\u0f0b\u0f60\u0f51\u0f72\u0f0b\u0f42\u0f61\u0f66\u0f0b\u0f68\u0f7a\u0f56\u0f0b\u0f42\u0f4f\u0f44\u0f0b\u0f60\u0f56\u0f51\u0f0d \u0f42\u0f5e\u0f72\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f60\u0f56\u0f51\u0f0b\u0f61\u0f7c\u0f51\u0f0b\u0f58\u0f72\u0f0b\u0f51\u0f44\u0f0b \u0f60\u0f42\u0f7c\u0f0b\u0f56\u0f59\u0f74\u0f42\u0f66\u0f0b\u0f56\u0f4f\u0f74\u0f56\u0f0b\u0f54\u0f60\u0f72\u0f0b\u0f42\u0fb3\u0f7c\u0f42\u0f0b\u0f62\u0f72\u0f58\u0f0b\u0f5a\u0f74\u0f0b\u0f62\u0f90\u0fb1\u0f44\u0f58\u0f0b\u0f45\u0f72\u0f42\u0f0b\u0f66\u0f9f\u0f7c\u0f53\u0f58\u0f0b\u0f68\u0f72\u0f53\u0f0d",
            "\u0f60\u0f47\u0f74\u0f42\u0f0b\u0f66\u0fa4\u0fb1\u0f7c\u0f51\u0f0b\u0f51\u0f44\u0f0b\u0f58\u0f42\u0fb1\u0f7c\u0f42\u0f66\u0f0b\u0f50\u0f56\u0f66\u0f0b\u0f5a\u0f74\u0f0d",
            "\u0f61\u0f72\u0f42\u0f0b\u0f66\u0fa3\u0f7c\u0f51\u0f0b\u0f46\u0f0b\u0f58\u0f49\u0f58\u0f0d",
    ];

    private static string[] Lang_ti() =>
