            "Discord, WhatsApp, \u0422\u0435\u043b\u0435\u0433\u0440\u0430\u043c\u043c\u0430, \u0421\u0438\u0433\u043d\u0430\u043b, \u041c\u0430\u0439\u043a\u0440\u043e\u0441\u043e\u0444\u0442 \u041a\u043e\u043c\u0430\u043d\u0434\u0430\u043b\u0430\u0440\u044b, \u0417\u0443\u0440\u043b\u0430\u0443, \u0421\u043b\u0430\u043a, ChatGPT, Spotify, VLC, Google Drive, OBS \u0441\u0442\u0443\u0434\u0438\u044f\u0441\u0435, VS \u043a\u043e\u0434\u044b, \u04bb\u04d9\u043c \u043c\u0435\u0434\u0430\u043b\u044c.",
            "YouTube, Instagram, TikTok, Facebook, Messenger, \u04bb\u04d9\u043c Google \u041a\u0430\u0440\u0442\u0430\u043b\u0430\u0440 Windows \u043a\u0443\u0448\u044b\u043c\u0442\u0430\u043b\u0430\u0440\u044b \u044f\u043a\u0438 PWA \u0438\u0442\u0435\u043f \u0443\u0440\u043d\u0430\u0448\u0442\u044b\u0440\u044b\u043b\u0433\u0430\u043d\u0434\u0430 \u0430\u0447\u044b\u043a\u043b\u0430\u043d\u0430.",
            ".Exe, .lnk, \u044f\u043a\u0438 .appref-ms \u0444\u0430\u0439\u043b\u044b\u043d \u04e9\u0441\u0442\u04d9\u04af \u04e9\u0447\u0435\u043d \u04e9\u0441\u0442\u04d9 ADD APP \u043a\u0443\u043b\u043b\u0430\u043d\u044b\u0433\u044b\u0437. \u041a-\u041b\u0430\u043d\u0447\u0435\u0440\u0434\u0430\u043d \u0447\u044b\u0433\u0430\u0440\u0443 \u04e9\u0447\u0435\u043d \u0430\u043d\u044b\u04a3 \u043a\u0430\u0440\u0442\u0430\u0441\u044b\u043d\u0430 \u0443\u04a3 \u0442\u04e9\u0439\u043c\u04d9 \u0431\u0435\u043b\u04d9\u043d \u0431\u0430\u0441\u044b\u0433\u044b\u0437. \u0423\u0440\u043d\u0430\u0448\u0442\u044b\u0440\u044b\u043b\u0433\u0430\u043d \u04bb\u04d9\u043c \u044d\u0448\u043b\u04d9\u0442\u0435\u043f \u0497\u0438\u0431\u04d9\u0440\u0435\u043b\u04d9 \u0442\u043e\u0440\u0433\u0430\u043d \u043a\u0443\u0448\u044b\u043c\u0442\u0430\u043b\u0430\u0440 \u0433\u044b\u043d\u0430 \u043a\u04af\u0440\u0441\u04d9\u0442\u0435\u043b\u04d9.",
            "\u041a\u0443\u0448\u044b\u043c\u0442\u0430\u043b\u0430\u0440 \u04bb\u04d9\u043c \u043a\u044b\u0441\u043a\u0430 \u044e\u043b\u043b\u0430\u0440",
            "\u0411\u0430\u0440\u043b\u044b\u043a \u0444\u0430\u0439\u043b\u043b\u0430\u0440",
    ];
}
